// Quote quotes a trade. The result holds the transaction that executes it. Amounts are in the
// input token's smallest unit (wei for ETH). Set Referrer to earn the trade referral reward.
// Nothing is signed or sent: pass the returned call to your wallet.
//
// POST /quote
func (c *Client) Quote(ctx context.Context, req *QuoteRequest) (*QuoteResponse, error) {
	if req == nil {
		return nil, fmt.Errorf("zora: Quote needs a request")
	}
	q := url.Values{}
	var resp QuoteResponse
	if err := c.Do(ctx, "POST", "/quote", q, req, &resp); err != nil {
		return nil, err
	}
	return &resp, nil
}

